import { randomBytes } from 'node:crypto'
import { mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'

// Keys are generated by the server (ids and hashes), never taken from user
// input — but the driver still refuses anything that could escape its root.
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/_.-]*$/

export class LocalStorageDriver {
  constructor(rootDir) {
    this.root = path.resolve(rootDir)
  }

  resolveKey(key) {
    if (typeof key !== 'string' || !SAFE_KEY.test(key) || key.includes('..') || key.includes('//') || key.endsWith('/')) {
      throw new Error('Invalid storage key.')
    }
    const target = path.resolve(this.root, key)
    const relative = path.relative(this.root, target)
    if (relative.startsWith('..') || path.isAbsolute(relative)) throw new Error('Invalid storage key.')
    return target
  }

  /**
   * Writes atomically (temp file + rename) so a crash never leaves a
   * half-written file under a real key. With `immutable`, an existing file of
   * the same size is left untouched (content-addressed keys never change).
   */
  async put(key, buffer, { immutable = false } = {}) {
    const target = this.resolveKey(key)
    if (immutable) {
      const existing = await stat(target).catch(() => null)
      if (existing && existing.size === buffer.length) return
    }
    await mkdir(path.dirname(target), { recursive: true })
    const temp = `${target}.tmp-${randomBytes(6).toString('hex')}`
    try {
      await writeFile(temp, buffer, { flag: 'wx' })
      await rename(temp, target)
    } catch (err) {
      await rm(temp, { force: true }).catch(() => {})
      throw err
    }
  }

  async get(key) {
    return readFile(this.resolveKey(key))
  }

  async exists(key) {
    return stat(this.resolveKey(key)).then((s) => s.isFile(), () => false)
  }

  async delete(key) {
    await rm(this.resolveKey(key), { force: true })
  }
}
